`timescale 1ns/1ps
`include "mips_16_defs.v"
module mips_16_core_top_tb_0_v;

// === Global Sync Signal ===
reg llm_go_signal = 1;


	// Inputs
	reg clk;
	reg rst;

	// Outputs
	wire [`PC_WIDTH-1:0] pc;

	parameter CLK_PERIOD = 10;
	always #(CLK_PERIOD /2) 
		clk =~clk;
	integer i;
	integer test;

	// Instantiate the Unit Under Test (UUT)
	mips_16_core_top uut (
		.clk(clk), 
		.rst(rst), 
		.pc(pc)
	);

	initial begin
		// Initialize Inputs
		clk = 0;
		rst = 0;

		// Wait 100 ns for global reset to finish
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

		#100;

		// Add stimulus here
		#(CLK_PERIOD/2)
		#1
		display_debug_message;
		//test1;
		test2;
		$finish;
	end

	task display_debug_message;
		begin
			$display("\n***************************");
			$display("mips_16 core test");
			$display("***************************\n");
		end
	endtask

	task sys_reset;
		begin
			rst = 0;
			#(CLK_PERIOD*1) rst = 1;
			#(CLK_PERIOD*1) rst = 0;
		end
	endtask


	task test1;
		begin
			$readmemb("../bench/mips_16_core_top/test1.prog",uut.IF_stage_inst.imem.rom);
			$display("rom load successfully\n");
			$display("running test1\n");
			sys_reset;
			#1

			//#(CLK_PERIOD) test = 1;

			$monitor("current pc: %d ,instruction: %x", pc, uut.instruction);

			#(CLK_PERIOD*100)
			$monitoroff;
			display_all_regs;
			$display("ram[10] = %d", uut.MEM_stage_inst.dmem.ram[10]);
			//#(CLK_PERIOD*100) test = 0;
			sys_reset;

		end
	endtask

	task test2;
		begin
			$readmemb("../bench/mips_16_core_top/test2.prog",uut.IF_stage_inst.imem.rom);
			$display("rom load successfully\n");
			$display("running test2\n");
			$display("multiply R3=R1*R2\n");
			sys_reset;
			display_all_regs;
			#1
			test = 2;

			//#(CLK_PERIOD) test = 1;

			$monitor("current pc: %d ,instruction: %x", pc, uut.instruction);

			#(CLK_PERIOD*400)
			$monitoroff;
			display_all_regs;

			test = 0;
			sys_reset;

		end
	endtask

	task display_all_regs;
		begin
			$display("display_all_regs:");
			$display("------------------------------");
			$display("R0\tR1\tR2\tR3\tR4\tR5\tR6\tR7");
			for(i=0; i<8; i=i+1)
					$write("%d\t",uut.register_file_inst.reg_array[i]);
			$display("\n------------------------------");
		end
	endtask


	always @ (test) begin
	wait(llm_go_signal==0) begin
	    case(test)
			// 1: begin
			    // $display("running test1\n");
				 // while(test == 1) begin
				    // @(uut.pc)
					// $display("current pc : %d",uut.pc);
					// if(uut.pc == 40) begin
						// #1
					    // branch_taken = 1;
						// branch_offset_imm = -30;
						// #(CLK_PERIOD*1) 
						// branch_taken =0;
						// branch_offset_imm = 0;
					// end
				 // end
			// end

			2: begin
			    $display("running test2\n");
				 while(test == 2) begin
				    @(pc)
					if(pc==6) begin
						$display("current pc : %d",uut.pc);
						display_all_regs();
					end

				 end
			end

		endcase
	end
	end

	        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "pc,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            //#10
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", pc);

            $fwrite(file_mantra, "\n");
          end
        end
		  // initial begin
    // wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

// #2000000
// $finish;
// end


// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. WAIT for original tests (synchronization)
    wait(llm_go_signal == 1);

    $display("LLM: Starting Deterministic Mutation Tests...");

    // 3. Initialize Instruction Memory (Clear ROM)
    // Accessing the simulation ROM directly to inject test program
    for (i = 0; i < 256; i = i + 1) begin
        uut.IF_stage_inst.imem.rom[i] = 16'h0000;
    end

    // 4. Load Test Program into ROM
    // We construct machine code instructions based on mips_16_defs.v

    // ---------------------------------------------------------
    // Basic Arithmetic & Logic
    // ---------------------------------------------------------
    // 0: ADDI R1, R0, 5      (R1 = 5)
    // Op: 1001, Dest: 001, Src1: 000, Imm: 000101
    uut.IF_stage_inst.imem.rom[0] = 16'b1001_001_000_000101; 

    // 1: ADDI R2, R0, 3      (R2 = 3)
    // Op: 1001, Dest: 010, Src1: 000, Imm: 000011
    uut.IF_stage_inst.imem.rom[1] = 16'b1001_010_000_000011;

    // 2: ADD R3, R1, R2      (R3 = 5+3 = 8)
    // Op: 0001, Dest: 011, Src1: 001, Src2: 010
    uut.IF_stage_inst.imem.rom[2] = 16'b0001_011_001_010_000;

    // 3: SUB R4, R1, R2      (R4 = 5-3 = 2)
    // Op: 0010, Dest: 100, Src1: 001, Src2: 010
    uut.IF_stage_inst.imem.rom[3] = 16'b0010_100_001_010_000;

    // 4: AND R5, R1, R2      (R5 = 5&3 = 1)
    // Op: 0011, Dest: 101, Src1: 001, Src2: 010
    uut.IF_stage_inst.imem.rom[4] = 16'b0011_101_001_010_000;

    // 5: OR  R6, R1, R2      (R6 = 5|3 = 7)
    // Op: 0100, Dest: 110, Src1: 001, Src2: 010
    uut.IF_stage_inst.imem.rom[5] = 16'b0100_110_001_010_000;

    // 6: XOR R7, R1, R2      (R7 = 5^3 = 6)
    // Op: 0101, Dest: 111, Src1: 001, Src2: 010
    uut.IF_stage_inst.imem.rom[6] = 16'b0101_111_001_010_000;

    // ---------------------------------------------------------
    // Shift Operations (Signed vs Unsigned)
    // ---------------------------------------------------------
    // 7: ADDI R1, R0, -8     (R1 = 0xFFF8)
    // Imm: -8 = 111000 (6-bit 2's comp)
    uut.IF_stage_inst.imem.rom[7] = 16'b1001_001_000_111000;

    // 8: ADDI R2, R0, 1      (R2 = 1)
    uut.IF_stage_inst.imem.rom[8] = 16'b1001_010_000_000001;

    // 9: SR  R3, R1, R2      (R3 = 0xFFFC, Arithmetic Shift)
    // Op: 0111, Dest: 011, Src1: 001, Src2: 010
    uut.IF_stage_inst.imem.rom[9] = 16'b0111_011_001_010_000;

    // 10: SRU R4, R1, R2     (R4 = 0x7FFC, Logical Shift)
    // Op: 1000, Dest: 100, Src1: 001, Src2: 010
    uut.IF_stage_inst.imem.rom[10] = 16'b1000_100_001_010_000;

    // ---------------------------------------------------------
    // Memory Operations (Store then Load)
    // ---------------------------------------------------------
    // 11: ADDI R1, R0, 15    (R1 = 15)
    uut.IF_stage_inst.imem.rom[11] = 16'b1001_001_000_001111;

    // 12: ST R1, R0, 10      (Mem[10] = 15)
    // Op: 1011, Data(Dest): 001, Base(Src1): 000, Imm: 001010
    uut.IF_stage_inst.imem.rom[12] = 16'b1011_001_000_001010;

    // 13: NOP (Wait for write)
    uut.IF_stage_inst.imem.rom[13] = 16'h0000;

    // 14: LD R2, R0, 10      (R2 = Mem[10] = 15)
    // Op: 1010, Dest: 010, Base(Src1): 000, Imm: 001010
    uut.IF_stage_inst.imem.rom[14] = 16'b1010_010_000_001010;

    // ---------------------------------------------------------
    // Branching (Taken and Not Taken)
    // ---------------------------------------------------------
    // 15: ADDI R5, R0, 0     (R5 = 0)
    uut.IF_stage_inst.imem.rom[15] = 16'b1001_101_000_000000;

    // 16: BZ R5, offset=2    (Branch Taken, Skip next)
    // Op: 1100, Cond(Dest): 000(Z), Src1: 101, Imm: 000010
    uut.IF_stage_inst.imem.rom[16] = 16'b1100_000_101_000010;

    // 17: ADDI R6, R0, 99    (Should be skipped)
    uut.IF_stage_inst.imem.rom[17] = 16'b1001_110_000_111111;

    // 18: ADDI R6, R0, 1     (Target, R6 = 1)
    uut.IF_stage_inst.imem.rom[18] = 16'b1001_110_000_000001;

    // ---------------------------------------------------------
    // Pipeline Hazard (RAW)
    // ---------------------------------------------------------
    // 19: ADD R1, R6, R6     (R1 = 1+1 = 2)
    uut.IF_stage_inst.imem.rom[19] = 16'b0001_001_110_110_000;

    // 20: ADD R2, R1, R1     (R2 = 2+2 = 4) - RAW Hazard on R1
    // This tests the hazard detection unit's ability to stall
    uut.IF_stage_inst.imem.rom[20] = 16'b0001_010_001_001_000;

    // 5. Apply Reset to Start Execution
    rst = 1;
    #20;
    rst = 0;

    // 6. Wait for Execution
    // Approx 25 instructions * 5 cycles/inst * 10ns/cycle = 1250ns
    // Adding buffer to ensure all instructions complete
    #2000;

    // 7. Handover
    $display("LLM: Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #2000000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

